from collections import deque

class UnboundedConsumer:
    def __init__(self):
        self.queue = deque()
    def push(self, msg):
        self.queue.append(msg)
    def lag(self):
        return len(self.queue)

class BoundedConsumer:
    def __init__(self, maxsize=5):
        self.queue = deque(maxlen=maxsize)
        self.dropped = 0
    def push(self, msg):
        if len(self.queue) >= self.queue.maxlen:
            self.dropped += 1
        self.queue.append(msg)
    def lag(self):
        return len(self.queue)

unbounded = UnboundedConsumer()
bounded = BoundedConsumer(maxsize=5)

for i in range(50):
    unbounded.push(f"tick_{i}")
    bounded.push(f"tick_{i}")

print("=== SLOW CONSUMER BUFFER FORENSICS ===")
print(f"Unbounded Buffer Lag:  {unbounded.lag()} items (RAM Risk: CRITICAL)")
print(f"Bounded Buffer Lag:    {bounded.lag()} items (RAM Risk: BOUNDED)")
print(f"Bounded Discard Count: {bounded.dropped} stale frames dropped")
print("Memory safety enforced via bounded eviction.")

