import asyncio

class ConnectionHub:
    def __init__(self, queue_limit=3):
        self.active_clients = {}
        self.limit = queue_limit
        self.evictions = []

    def register(self, client_id):
        self.active_clients[client_id] = asyncio.Queue(maxsize=self.limit)

    def broadcast(self, message):
        evict_list = []
        for cid, q in self.active_clients.items():
            try:
                q.put_nowait(message)
            except asyncio.QueueFull:
                q.get_nowait()
                q.put_nowait(message)
        for cid in evict_list:
            del self.active_clients[cid]
            self.evictions.append(cid)

hub = ConnectionHub(queue_limit=2)
hub.register("client_fast")
hub.register("client_slow")

# Broadcast messages beyond queue limit (fast client consumes immediately)
for idx in range(4):
    hub.broadcast(f"tick_payload_{idx}")
    if "client_fast" in hub.active_clients:
        hub.active_clients["client_fast"].get_nowait()

print("=== WEBSOCKET BROADCAST HUB LAB ===")
print(f"Active Healthy Clients: {list(hub.active_clients.keys())}")
print(f"Evicted Slow Consumers: {hub.evictions}")
print(f"Fast Client Backlog:    {hub.active_clients['client_fast'].qsize()} items")
print("Deterministic slow consumer eviction verified.")

def mock_llm_token_stream():
    tokens = ["FastAPI", " ", "v0.115", " ", "Streaming", " ", "Active"]
    for t in tokens:
        yield t

def sse_gateway_handler(max_tokens=3):
    emitted = []
    for idx, token in enumerate(mock_llm_token_stream()):
        if idx >= max_tokens:
            emitted.append("[DISCONNECTED_ABORT]")
            break
        emitted.append(f"data: {json_token(token)}\n\n")
    return emitted

def json_token(t):
    return f'"token": "{t}"' 

