import asyncio

class MicroserviceStreamingSubsystem:
    def __init__(self):
        self.ws_subscribers = {}
        self.stats = {"broadcasts": 0, "sse_frames": 0, "evictions": 0}

    def subscribe_ws(self, uid, max_queue=5):
        self.ws_subscribers[uid] = asyncio.Queue(maxsize=max_queue)

    def broadcast_ws(self, message):
        to_evict = []
        for uid, q in self.ws_subscribers.items():
            try:
                q.put_nowait(message)
            except asyncio.QueueFull:
                to_evict.append(uid)
        for uid in to_evict:
            del self.ws_subscribers[uid]
            self.stats["evictions"] += 1
        self.stats["broadcasts"] += 1

    def stream_sse(self, items):
        for item in items:
            self.stats["sse_frames"] += 1
            yield f"event: tick\ndata: {item}\n\n"

subsystem = MicroserviceStreamingSubsystem()
subsystem.subscribe_ws("trader_alpha")
subsystem.subscribe_ws("trader_beta")

# Broadcast 3 ticks (trader_alpha drains queue, trader_beta lags and is evicted)
for i in range(3):
    subsystem.broadcast_ws(f"tick_{i}")
    if "trader_alpha" in subsystem.ws_subscribers:
        subsystem.ws_subscribers["trader_alpha"].get_nowait()

sse_results = list(subsystem.stream_sse(["price_101.5", "price_102.0"]))

print("=== STREAMING & WEBSOCKET SUBSYSTEM SYNTHESIS ===")
print(f"Broadcast Events Dispatched: {subsystem.stats['broadcasts']}")
print(f"SSE Frames Emitted:         {subsystem.stats['sse_frames']}")
print(f"Active WebSocket Clients:   {len(subsystem.ws_subscribers)}")
print(f"Slow Consumer Evictions:    {subsystem.stats['evictions']}")
print("Full streaming and WebSocket synthesis verified.")
